async function (vars) {
    var data = await api.get("DocumentManagement/File(" +vars.fileId + ")?$expand=Contents($select=Id,FileId,Description,Size,CreatedBy,CreatedOn,Version)");
var g = new GridWidget(vars.element, { data: data.Contents });
    g.groupable = false;
    g.editable = true;
    g.pageable = false;
    const fileFunctionsCol = function (data) {
        const fileLink = session.apiRoot + "/DMS/" + file.Path + "?version=" + data.Version + "&t=" + session.token;
        let html = "<a name='download' target='_blank' href='" + fileLink + "'><span class='k-icon k-i-download'></span>[resource_displayname[DownloadFileVersion]]</a>";
        if (!readOnly) html += "<a name='deleteFileVersion' href='' data-version='" + data.Version + "'><span class='k-icon k-i-delete'></span>[resource_displayname[DeleteFileVersion]]</a>";
        return html;
    };
    g.columns = [
        { width: 40, field: "Version", title: "\#", editable: false },
        { title: "[resource_shortdisplayname[Name]]", template: file.Name },
        { field: 'Size', width: 80, title: "[resource_shortdisplayname[Size]]" },
        { width: 200, field: "CreatedBy", title: "[resource_shortdisplayname[CreatedBy]]", editable: false },
        { width: 130, field: "CreatedOn", title: "[resource_shortdisplayname[CreatedOn]]", editable: false, template: function (data) { return kendo.htmlEncode(kendo.toString(new Date(data.CreatedOn), type.dateFormat + " HH:mm:ss")); } },
        { width: 300, template: fileFunctionsCol }
    ];
    vars.FileVersionsGrid = g;
    return g;
}
